WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_c_multi'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '多人合作', 'kp-eng-c-multi', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多人合作"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "无论多少人参与，万变不离其宗：寻找所有时间的最小公倍数。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目给出三个或三个以上主体单独完成工程的时间（如甲、乙、丙）。最后求他们以不同组合方式合作的时间。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "W = LCM(T_A, T_B, T_C) \\quad \\Rightarrow \\quad P_{总} = P_A + P_B + P_C"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出所有单干时间] --> B[求最小公倍数作为总量 W]\nB --> C[算出每个人的单独效率]\nC --> D[根据题目要求的组合, 将参与人的效率相加得到当前阶段 P总]\nD --> E[用 W / P总 求出答案]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 一项工程，甲需10天，乙需12天，丙需15天。三人合作需几天？选项：A. 3  B. 4  C. 5  D. 6"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋总量：10, 12, 15 的最小公倍数为 60。设 W = 60。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求效率：P甲 = 6, P乙 = 5, P丙 = 4。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "合效率：P总 = 6 + 5 + 4 = 15。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求时间：T = W ÷ P总 = 60 ÷ 15 = 4 天。选 B。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "公倍数找错：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果找不到三个数的最小公倍数，宁愿找一个稍微大点的公倍数（比如直接把三个数乘起来的一部分），也千万不要带分数算！效率可以是小数，但总量一定要赋得好除。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "对常见三元公倍数组合形成反射：(10,12,15)->60；(12,15,20)->60；(20,30,60)->60。"}]}]}$$ AS jsonb), NULL, '多人合作的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "多人合作"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_c_multi", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
